                     std::vector<Operator>& outputs, Graph& graph)
{
    Status ret = SUCCESS;
    // 自定义代码：添加单算子定义到图中
    auto add1 = op::AddExample("add1");
    std::vector<int64_t> xShape = {32, 4, 4, 4};
    ADD_INPUT(1, x1, inDtype, xShape);
